WITH p AS (SELECT %s::date dfrom,%s::date dto,coalesce(%s::text,'') ma_vt,coalesce(%s::text,'') ma_kho,coalesce(%s::text,'') ma_lo,coalesce(%s::text,'') ma_khuon,%s::integer uid,%s::integer lim), s AS (SELECT p.*,u.user_id ok,coalesce(u.ds_branchs,'') bs,coalesce(u.is_super,0)=1 OR(coalesce(u.ds_branchs,'')='' AND coalesce(u.ds_stocks,'')='') unrestricted FROM p LEFT JOIN public.userinfo u ON u.user_id=p.uid), x AS (SELECT a.ma_kho,a.ma_vi_tri,a.data_tem->0->>'ma_vt' ma_vt,a.data_tem->0->>'ma_lo' ma_lo,coalesce(a.data_tem->0->>'die_no','') die_no,coalesce(a.data_tem->0->>'ma_khuon','') ma_khuon,(a.data_tem->0->>'so_luong')::numeric ton FROM public.intem_log a CROSS JOIN s WHERE s.ok IS NOT NULL AND a.nxt=1 AND a.status='1' AND a.date0 BETWEEN s.dfrom AND s.dto AND(s.ma_vt='' OR a.data_tem->0->>'ma_vt'=ANY(string_to_array(s.ma_vt,',')))AND(s.ma_kho='' OR a.ma_kho=ANY(string_to_array(s.ma_kho,',')))AND(s.ma_lo='' OR a.data_tem->0->>'ma_lo'=ANY(string_to_array(s.ma_lo,',')))AND(s.ma_khuon='' OR a.data_tem->0->>'ma_khuon'=ANY(string_to_array(s.ma_khuon,',')))AND(s.unrestricted OR EXISTS(SELECT 1 FROM public.dmkho k WHERE k.ma_kho=a.ma_kho AND k.ma_dvcs=ANY(string_to_array(s.bs,','))))), q AS (SELECT x.ma_vt,max(v.ten_vt) ten_vt,max(v.dvt) dvt,max(v.nh_vt6) nh_vt6,x.ma_lo,x.die_no,x.ma_kho,x.ma_vi_tri,x.ma_khuon,sum(x.ton) ton_vi_tri FROM x JOIN public.dmvt v ON v.ma_vt=x.ma_vt AND v.vt_ton_kho=true JOIN public.dmlo l ON l.ma_vt=x.ma_vt AND l.ma_lo=x.ma_lo GROUP BY x.ma_vt,x.ma_lo,x.die_no,x.ma_kho,x.ma_vi_tri,x.ma_khuon) SELECT q.*,count(*) OVER() total FROM q ORDER BY ma_vt,ma_lo,ma_kho,ma_vi_tri,ma_khuon LIMIT(SELECT lim FROM p);
